-- Maps a Lua list to children. `nil` results are skipped.
function ui.each(list, body)
	local out = {}
	for index, item in ipairs(list) do
		local node = body(item, index)
		if node ~= nil then
			table.insert(out, node)
		end
	end
	return out
end

-- Expressions: the closed function set, evaluated on the client. `and`, `or` and `not` are Lua keywords.
-- Boolean negation.
function ui.negate(a)
	return call("not", a)
end

-- True when every argument is truthy.
function ui.all(first, ...)
	return call("and", first, ...)
end

-- True when any argument is truthy.
function ui.any(first, ...)
	return call("or", first, ...)
end

-- Strict equality.
function ui.eq(a, b)
	return call("eq", a, b)
end

-- Strict inequality.
function ui.ne(a, b)
	return call("ne", a, b)
end

-- Less than.
function ui.lt(a, b)
	return call("lt", a, b)
end

-- Greater than.
function ui.gt(a, b)
	return call("gt", a, b)
end

-- Number addition.
function ui.add(a, b)
	return call("add", a, b)
end

-- Number subtraction.
function ui.sub(a, b)
	return call("sub", a, b)
end

-- `if(cond, then, else)`.
function ui.when(a, b, c)
	return call("if", a, b, c)
end

-- The first argument that is not null or empty.
function ui.coalesce(first, ...)
	return call("coalesce", first, ...)
end

-- Concatenate the arguments as text.
function ui.concat(first, ...)
	return call("concat", first, ...)
end

-- Length of a string or list.
function ui.len(a)
	return call("len", a)
end

-- True for null, an empty string or an empty list.
function ui.isEmpty(a)
	return call("isEmpty", a)
end

-- Upper-case text.
function ui.upper(a)
	return call("upper", a)
end

-- Lower-case text.
function ui.lower(a)
	return call("lower", a)
end

-- Formatting in the viewer's locale and time zone.
local fmt = {}
ui.fmt = fmt

-- Format a number in the viewer's locale.
function fmt.number(a, b)
	return call("fmt.number", a, b)
end

-- Format money in the viewer's locale.
function fmt.currency(a, b, c)
	return call("fmt.currency", a, b, c)
end

-- Format a ratio as a percentage.
function fmt.percent(a, b)
	return call("fmt.percent", a, b)
end

-- Format a byte count (KB, MB, ...).
function fmt.bytes(a, b)
	return call("fmt.bytes", a, b)
end

-- Format a date or instant in the viewer's locale and time zone.
function fmt.date(a, b)
	return call("fmt.date", a, b)
end

-- Format a time of day.
function fmt.time(a, b)
	return call("fmt.time", a, b)
end

-- Format a date and time.
function fmt.dateTime(a, b)
	return call("fmt.dateTime", a, b)
end

-- Relative time ("2 minutes ago"), ticking from `env.now`.
function fmt.relative(a, b)
	return call("fmt.relative", a, b)
end

-- Pick a plural form: `fmt.plural(n, {one, other})`.
function fmt.plural(a, b)
	return call("fmt.plural", a, b)
end

-- Join a list ("a, b and c").
function fmt.list(a, b)
	return call("fmt.list", a, b)
end

-- Client actions: run on the client with no round trip. Handlers take one, or a list mixing actions and functions.
local act = {}
ui.act = act

-- Write a client-managed or app-state ref.
function act.set(target, value)
	return { ["do"] = "set", ref = refPath(target), value = value }
end

-- Flip a boolean ref.
function act.toggle(target)
	return { ["do"] = "toggle", ref = refPath(target) }
end

-- Push a route (`{ name = "note", id = 7 }`) onto a navigation stack (the optional `stack` names it).
function act.push(route, stack)
	return { ["do"] = "nav.push", stack = stack, route = route }
end

-- Pop the top route.
function act.pop()
	return { ["do"] = "nav.pop" }
end

-- Pop to the root screen.
function act.popToRoot()
	return { ["do"] = "nav.popToRoot" }
end

-- Move focus to the node with this key.
function act.focus(key)
	return { ["do"] = "focus", key = key }
end

-- Scroll to the node with this key.
function act.scrollTo(key)
	return { ["do"] = "scrollTo", key = key }
end

-- Copy text to the clipboard.
function act.copy(text)
	return { ["do"] = "copy", text = text }
end

-- Report an event to the app (the handler of the node still runs on the host).
function act.emit(event, payload)
	return { ["do"] = "emit", event = event, payload = payload }
end

-- Run actions in order.
function act.seq(actions)
	return { ["do"] = "seq", actions = actions }
end

return ui
